        // Fund user with sufficient ether
        vm.deal(user, depositAmount * 2);
    }

    function test_TimestampManipulation() public {
        // Use positive future timestamps instead of past dates
        uint256 futureTime = block.timestamp + 1 days;

        // Setup deposit parameters
        vm.startPrank(user);
        vault.Deposit{value: depositAmount}();
        vm.stopPrank();

        console.log("--- BEFORE-Trigger Log Check ---");
        uint256 numLogsBefore = logger.History_length();
        require(numLogsBefore > 0, "No logs exist yet");

        ( , , , uint256 timeBefore, , ) = logger.History(numLogsBefore - 1);
        console.log("Last log timestamp BEFORE CashOut:", timeBefore);

        // Setup for cashout with future timestamp
        vm.warp(futureTime);  // Set to future time

        vm.startPrank(user);
        console.log("--- Trigger CashOut ---");
        uint256 initialUserBalance = user.balance;
        vault.CashOut(depositAmount);
        vm.stopPrank();

        console.log("--- AFTER-Trigger Log Check ---");
        // Check if new log entry has been added
        uint256 numLogsAfter = logger.History_length();
        require(numLogsAfter > numLogsBefore, "No new log created");

        ( , , , uint256 timeAfter, , ) = logger.History(numLogsAfter - 1);
        console.log("Last log timestamp AFTER CashOut:", timeAfter);

        // Verify state changes
        bool isTimestampManipulated = (timeAfter == futureTime);
        console.log("Timestamps equal futureTime?", isTimestampManipulated ? "YES" : "NO");

        assertEq(vault.balances(user), 0, "Vault balance should be zero after cashout");
        assertEq(user.balance, initialUserBalance + depositAmount, "User should receive ETH");

        // Final vulnerability verdict
        if (isTimestampManipulated) {
            console.log("Vulnerability Exists: Log recorded future timestamp successfully, allowing state changes with manipulated block.timestamp");
        } else {
            console.log("Vulnerability not Exist: Log did not record future timestamp, contract resisted timestamp manipulation");
        }
    }
}
